INSERT INTO `application_steps` VALUES (1,1,1,'Visit the Admissions Office or Contact an Agent','Contact the university\'s International Admissions Office directly or through a registered Myanmar education agent. They can guide you through the process and available scholarships.'),(2,1,2,'Prepare and Submit Your Documents','Prepare your academic transcripts, passport copy, English proficiency certificate, and two passport photographs. Submit these along with your completed application form.'),(3,1,3,'Receive and Accept Your Offer','The admissions team reviews your application within 2–4 weeks. If accepted, you will receive an offer letter by email. Accept by paying the acceptance deposit to confirm your place.'),(4,1,4,'Apply for a Non-Immigrant ED Visa','Once you have your offer letter, apply for a Thai Non-Immigrant ED (Education) Visa at the Royal Thai Embassy in Yangon. You will need the offer letter, passport, and supporting documents.'),(5,2,1,'Visit the Admissions Office or Contact an Agent','Contact the university\'s International Admissions Office directly or through a registered Myanmar education agent. They can guide you through the process and available scholarships.'),(6,2,2,'Prepare and Submit Your Documents','Prepare your academic transcripts, passport copy, English proficiency certificate, and two passport photographs. Submit these along with your completed application form.'),(7,2,3,'Receive and Accept Your Offer','The admissions team reviews your application within 2–4 weeks. If accepted, you will receive an offer letter by email. Accept by paying the acceptance deposit to confirm your place.'),(8,2,4,'Apply for a Non-Immigrant ED Visa','Once you have your offer letter, apply for a Thai Non-Immigrant ED (Education) Visa at the Royal Thai Embassy in Yangon. You will need the offer letter, passport, and supporting documents.'),(9,3,1,'Research Programs and Requirements','Visit the university\'s official international admissions page and verify entry 