INSERT INTO `scholarships` VALUES (1,1,'Bangkok University Merit Scholarship','Awarded to high-achieving international students in undergraduate programs. Covers partial tuition fees for the duration of study.',60000.00,'THB','Minimum GPA 3.0, international students, full-time enrollment.','2026-11-14','https://www.bangkokuniversity.ac.th/en/scholarship','Partial',1),(2,2,'Chulalongkorn University ASEAN Scholarship (TICA)','Prestigious scholarship by Thailand International Cooperation Agency (TICA) for outstanding ASEAN students. Covers full tuition, accommodation, and monthly stipend of THB 9,000.',240000.00,'THB','ASEAN nationality, under 35, bachelor degree equivalent, IELTS 6.0+, not receiving other government scholarships.','2027-05-15','https://www.chula.ac.th/en/academics/scholarship/','Full',1),(3,3,'Mahidol University International Scholarship (MUIS)','MUIS supports international graduate students in science, health, and engineering. Covers full tuition, living allowance THB 15,000/month, and round-trip airfare.',300000.00,'THB','International students, GPA 3.5+, Master or PhD in STEM or health sciences, under 35.','2027-04-30','https://graduate.mahidol.ac.th/scholar/','Full',1),(4,4,'Thammasat University International Merit Award','Partial scholarship for international students joining Thammasat international programs in law, economics, and social sciences. Awarded on academic excellence.',80000.00,'THB','GPA 3.2+ equivalent, applying to international program, strong motivation letter.','2027-07-31','https://tu.ac.th/en/scholarship','Partial',1),(5,5,'CMU Presidential Scholarship for International Students','Full scholarship for high-achieving international students at Chiang Mai University. Includes tuition, dormitory, and monthly allowance of THB 8,000.',180000.00,'THB','International students, top 10% of previous institution, applying to English-taught program.','2027-06-15','https://www1.reg.cmu.ac.th/scholarship/','Full',1),(6,6,'KMUTT International Technology Scholarship','50% tuition waiver plus research support for international students in engineering and innovation programs at King Mongkut University of Technology Thonburi.',120000.00,'THB','International students, GPA 3.0+ equivalent, applying to engineering or technology Bachelor or Master.','2027-08-31','https://www.kmutt.ac.th/en/scholarship','Partial',1),(7,7,'Kasetsart University ASEAN Agricultural Scholarship','Partial scholarship for ASEAN international students in agriculture, veterinary, and environmental studies. Priority for students from developing ASEAN nations.',50000.00,'THB','ASEAN nationality preferred, GPA 3.0+, agriculture-related faculty application.','2027-09-30','https://www.ku.ac.th/scholarship','Partial',0),(8,8,'ABAC International Student Excellence Award','Tuition reduction for international students with excellent academic records at Assumption University (ABAC). Renewable each semester if GPA 3.3+ is maintained.',90000.00,'THB','International students, GPA 3.3+ per semester, full-time undergraduate or graduate enrollment.','2027-07-15','https://www.au.edu/scholarship','Tuition Only',1),(9,9,'AIT Full Scholarship (AITFS)','One of the most prestigious awards at the Asian Institute of Technology. Covers full tuition, thesis costs, and monthly stipend of THB 12,000 for Master and PhD students.',480000.00,'THB','Outstanding academic record (top of class), Master or PhD applicant, strong research proposal, TOEFL 550 or IELTS 6.0 minimum.','2026-10-15','https://www.ait.ac.th/admissions/scholarships/','Full',1),(10,10,'Rangsit University International Student Bursary','Partial financial support for international students in pharmacy, aviation, or creative arts. Awarded based on financial need and academic merit.',40000.00,'THB','International students, demonstrated financial need, GPA 2.8+, full enrollment.','2027-10-31','https://www.rsu.ac.th/scholarship','Partial',0),(11,11,'ASEAN Undergraduate Scholarship (MOE Singapore — NUS)','One of Singapore most prestigious scholarships funded by the Ministry of Education. Covers full NUS tuition, hostel, a monthly stipend of SGD 500, and return airfare from home country.',28000.00,'SGD','ASEAN nationality excluding Singapore, outstanding A-level or IB results, under 21, strong leadership and community involvement.','2027-12-01','https://www.nus.edu.sg/oam/scholarships/freshmen/university-scholarships/asean-undergraduate-scholarship','Full',1),(12,12,'Nanyang Scholarship (NTU)','NTU flagship merit scholarship covering full tuition, accommodation, SGD 400/month allowance, and overseas immersion programme. One of the most competitive scholarships in Singapore.',26600.00,'SGD','Minimum 90th percentile academic results, strong co-curricular achievements, any nationality, applying for NTU undergraduate programmes.','2027-11-30','https://www.ntu.edu.sg/admissions/undergraduate/scholarships/nanyang-scholarship','Full',1),(13,13,'SMU Global Impact Scholarship','Awarded to students with potential to make a significant global impact. Covers full SMU tuition, mentorship with industry leaders, and networking opportunities.',18000.00,'SGD','Any nationality, strong academic record, proven leadership, clear vision of impact, applying for any SMU undergraduate degree.','2027-10-15','https://www.smu.edu.sg/admission/financing-your-education/scholarships','Full',1),(14,14,'SUTD Merit Scholarship','Recognises students with strong potential in design and technology innovation. Covers full SUTD tuition and a monthly stipend of SGD 300.',22000.00,'SGD','Excellent academic standing, passion for design thinking and engineering, any nationality.','2027-12-15','https://www.sutd.edu.sg/Admissions/Undergraduate/Scholarships','Full',1),(15,15,'SUSS Academic Excellence Award','Partial scholarship for students excelling at SUSS in social work, psychology, law, and community studies programmes.',8000.00,'SGD','GPA 3.5+, Singapore PR or international, full-time undergraduate, commitment to social service.','2027-09-01','https://www.suss.edu.sg/about-suss/financial-matters/scholarships','Partial',0),(16,16,'JCU Singapore Excellence Scholarship','Tuition reduction for academically strong students at JCU Singapore. Renewable each trimester if GPA 5.0+ (JCU scale) is maintained.',9000.00,'SGD','International students, GPA 3.0+ equivalent, applying for Bachelor programs in IT, business, or marine science.','2027-11-01','https://www.jcu.edu.sg/scholarships','Tuition Only',1),(17,17,'SIM Academic Merit Award','Partial first-year tuition fee waiver for high-potential students joining SIM affiliated university programmes. Partner universities include Coventry, Birmingham, and UB.',5000.00,'SGD','A-level or diploma equivalent, GPA 3.0+, applying to any SIM-affiliated partner university programme.','2027-08-31','https://www.sim.edu.sg/scholarships','Partial',0),(18,18,'PSB Academy International Student Scholarship','Partial tuition scholarship for high-achieving international students in business, engineering, or IT at PSB Academy. Offered in partnership with Scottish Qualifications Authority.',4000.00,'SGD','International students, GPA 3.0+, applying to PSB Academy diploma or degree programmes.','2027-10-31','https://www.psb-academy.edu.sg/scholarships','Partial',0),(19,19,'Kaplan Singapore Higher Education Bursary','Financial assistance for eligible students pursuing higher education at Kaplan Singapore. Based on both financial need and academic merit.',3000.00,'SGD','Financial need demonstrated, minimum academic entry requirements met, applying for diploma or degree programmes.','2026-11-10','https://www.kaplan.com.sg/scholarships','Tuition Only',0),(20,20,'MDIS International Excellence Scholarship','Merit-based 25% tuition fee reduction for international students pursuing MDIS programmes in business, fashion, or psychology through UK partner universities.',4500.00,'SGD','International students, strong academic results, full-time MDIS enrolment, good character reference required.','2026-11-16','https://www.mdis.edu.sg/scholarships','Partial',0),(21,21,'Malaysia International Scholarship (MIS) — University of Malaya','Prestigious Government of Malaysia scholarship for international postgraduate students at top Malaysian universities. Covers full tuition, monthly stipend RM 1,500, and airfare.',60000.00,'MYR','International students (non-Malaysian), under 45 (postgraduate), CGPA 3.5+ equivalent, not holding another scholarship.','2027-05-31','https://biasiswa.mohe.gov.my/INTER/','Full',1),(22,22,'UPM Graduate Research Fellowship','Research scholarship for postgraduate students at Universiti Putra Malaysia in agriculture, food science, and biotechnology. Covers full tuition and RM 1,200/month stipend.',18000.00,'MYR','International applicants for Master by Research or PhD at UPM, first-class honours equivalent, strong research proposal.','2027-06-30','https://www.upm.edu.my/student/scholarship','Full',1),(23,23,'UTM International Postgraduate Scholarship','For outstanding international postgraduate students in engineering and technology at UTM. Covers full tuition and RM 1,000/month living allowance.',15000.00,'MYR','CGPA 3.5+ for Master, 3.7+ for PhD, engineering or technology research proposal required.','2027-07-31','https://www.utm.my/scholarship','Full',1),(24,24,'UKM International Student Excellence Award','Merit scholarship for international students joining UKM undergraduate and postgraduate programmes based on exceptional academic performance and leadership.',12000.00,'MYR','CGPA 3.5+, strong co-curricular record, any UKM programme.','2027-08-15','https://www.ukm.my/scholarship','Partial',1),(25,25,'USM Fellowship for International Students','Competitive fellowship for international PhD students at Universiti Sains Malaysia in health, engineering, and natural sciences. Includes full tuition waiver and RM 1,200/month stipend.',20000.00,'MYR','International PhD applicants, first-class honours equivalent, strong publications preferred.','2027-04-30','https://www.usm.my/scholarship','Full',1),(26,26,'Taylor\'s University Presidential Scholarship','Taylor\'s highest scholarship award. Covers 100% tuition fees for the entire programme duration. Awarded for all-round excellence in academics, leadership, and co-curricular activities.',80000.00,'MYR','Minimum 9As SPM or equivalent, strong leadership record, applying for Taylor undergraduate programmes, open to all nationalities.','2027-06-30','https://university.taylors.edu.my/en/study-at-taylors/fees-and-scholarships.html','Full',1),(27,27,'Monash International Merit Scholarship','Up to 50% tuition fee reduction for high-achieving international students at Monash University Malaysia. One of the most sought-after private university scholarships in Malaysia.',40000.00,'MYR','International students, minimum 90% in previous academic qualifications, any Monash Malaysia undergraduate degree.','2027-11-30','https://www.monash.edu.my/study/scholarships','Partial',1),(28,28,'Sunway University Excellence Scholarship','Merit scholarship ranging from 10% to 50% tuition waiver depending on academic results. One of the most popular awards among Malaysian private universities.',25000.00,'MYR','Minimum 5As SPM or equivalent, applying for Sunway University undergraduate, maintain CGPA 3.0 to renew.','2026-10-31','https://www.sunway.edu.my/university/scholarships','Partial',0),(29,29,'APU International Scholarship (Technology)','30-50% tuition waiver for international students in computing, cybersecurity, and data science at Asia Pacific University of Technology & Innovation.',20000.00,'MYR','International students, CGPA 3.0+ equivalent, applying for APU computing or technology programmes.','2026-11-05','https://www.apu.edu.my/scholarship','Tuition Only',1),(30,30,'HELP University Vice-Chancellor\'s Award','Prestige award covering partial tuition fees for top-performing students joining HELP University economics, psychology, and law programmes.',12000.00,'MYR','Minimum 5Bs SPM or equivalent, applying for HELP undergraduate programmes, strong interview performance.','2027-08-31','https://www.help.edu.my/scholarship','Partial',0),(31,11,'NUS Science & Technology Undergraduate Scholarship','Awarded to outstanding students pursuing science and technology degrees at NUS. Covers full tuition, accommodation, monthly allowance of SGD 500, and funding for overseas attachment.',28000.00,'SGD','Excellent A-level or IB results in science/mathematics subjects, any nationality, applying for science or engineering undergraduate at NUS.','2027-12-01','https://www.nus.edu.sg/oam/scholarships/freshmen/university-scholarships','Full',1),(32,12,'NTU CN Yang Scholars Programme','Elite interdisciplinary scholarship at NTU named after Nobel laureate Prof Chen-Ning Yang. Provides enhanced curriculum, research opportunities, and full financial support including overseas study.',26600.00,'SGD','Exceptional academic achievers (top 1%), strong interest in science and innovation, any nationality applying to NTU.','2027-11-30','https://www.ntu.edu.sg/cnyang','Full',1),(33,13,'SMU-Lien Foundation Social Innovation Scholarship','For students with a strong passion for social entrepreneurship and community development. Covers partial tuition and provides mentorship and project funding to launch social initiatives.',10000.00,'SGD','Any nationality, demonstrated commitment to social causes, applying for any SMU undergraduate degree, strong essay on social impact vision.','2027-10-15','https://www.smu.edu.sg/admission/financing-your-education/scholarships','Partial',1),(34,14,'SUTD-MIT Exchange Scholarship','Exclusive scholarship for SUTD students selected for the MIT cross-collaboration programme. Covers travel, accommodation, and research expenses for a semester at MIT, plus partial SUTD tuition waiver.',15000.00,'SGD','Current SUTD students with CGPA 3.8+, strong research record, faculty recommendation required. Only available after first year at SUTD.','2027-12-15','https://www.sutd.edu.sg/Admissions/Undergraduate/Scholarships','Partial',0),(35,16,'JCU Singapore Community Leadership Award','Recognises students who demonstrate exceptional community leadership and social contribution alongside academic achievement at JCU Singapore.',5000.00,'SGD','JCU Singapore students or applicants, demonstrated leadership in community or social activities, GPA equivalent 3.0+.','2027-11-01','https://www.jcu.edu.sg/scholarships','Partial',0),(36,2,'TICA Development Scholarship — Chulalongkorn','The Thailand International Cooperation Agency (TICA) offers annual scholarships to students from developing countries to pursue Master degrees at Chulalongkorn. Covers full tuition, living expenses, and return airfare.',210000.00,'THB','Nationals of TICA partner developing countries (including Myanmar), under 35, applying for Master programmes, working in public service recommended.','2027-04-30','https://www.tica.thaigov.net/main/en/scholarship','Full',1),(37,3,'Mahidol-Wittayanusorn Science Scholarship','Supports outstanding international students in natural and applied sciences at Mahidol. Partial tuition waiver with priority for students from ASEAN countries with exceptional science backgrounds.',150000.00,'THB','ASEAN nationality, strong science background (biology, chemistry, physics), applying to Mahidol science or medical programmes, GPA 3.5+.','2027-04-30','https://graduate.mahidol.ac.th/scholar/','Partial',1),(38,9,'AIT-JICA Japanese Government Scholarship','Co-funded by the Japan International Cooperation Agency (JICA) and AIT. Fully funds Master and PhD students from ASEAN developing nations in engineering, environment, and management fields.',400000.00,'THB','Nationals of JICA partner countries (Myanmar eligible), under 35, applying for AIT Master or PhD, currently employed in relevant public sector preferred.','2028-02-28','https://www.ait.ac.th/admissions/scholarships/jica-scholarship/','Full',1),(39,6,'KMUTT Innovation & Entrepreneurship Scholarship','For students with outstanding potential in technology entrepreneurship and innovation at KMUTT. Includes mentoring by industry leaders, co-working space access, and seed funding for startup projects.',80000.00,'THB','International students applying to KMUTT engineering or technology programmes, demonstrated innovation project or startup idea, GPA 3.2+.','2027-08-31','https://www.kmutt.ac.th/en/scholarship','Partial',1),(40,5,'CMU Northern Thailand Cultural Scholarship','Unique scholarship celebrating Chiang Mai cultural heritage for international students studying Thai language, culture, history, or social sciences at CMU alongside their main degree.',60000.00,'THB','International students enrolled in any CMU programme, taking at least one Thai cultural or language course, good standing.','2027-06-15','https://www1.reg.cmu.ac.th/scholarship/','Partial',0),(41,4,'AUN-SEED Net Graduate Scholarship — Thammasat','ASEAN University Network scholarship for postgraduate students in engineering and natural resources. Funded by JICA, covers full tuition at Thammasat and living allowance.',180000.00,'THB','ASEAN nationals (Myanmar eligible), applying for Master or PhD in engineering or natural resource management at Thammasat, under 35.','2027-05-31','https://www.seed-net.org/scholarship/','Full',1),(42,21,'UM International Excellence Award','Merit-based award for outstanding international students admitted to undergraduate or postgraduate programmes at University of Malaya. Covers partial tuition fees based on academic results.',15000.00,'MYR','International students, CGPA 3.7+ or equivalent, applying for UM undergraduate or postgraduate, strong academic portfolio.','2027-05-31','https://umstudent.um.edu.my/scholarship','Partial',1),(43,27,'Monash Vice-Chancellor Excellence Scholarship','Top-tier scholarship at Monash University Malaysia covering 75% tuition fee waiver. Awarded to truly exceptional students with perfect or near-perfect academic records.',60000.00,'MYR','Minimum 95% in previous academic qualifications or equivalent (9As and above SPM), any nationality, any Monash Malaysia undergraduate degree.','2027-11-30','https://www.monash.edu.my/study/scholarships','Partial',1),(44,26,'Taylor\'s Excellence Award','Separate from the Presidential Scholarship, Taylor\'s Excellence Award provides 50% tuition waiver for students with outstanding A-level, STPM or IB results. More widely available than the Presidential Award.',40000.00,'MYR','5As in A-level/STPM or equivalent, or IB score 38+, applying for Taylor undergraduate programmes, any nationality.','2026-09-27','https://university.taylors.edu.my/en/study-at-taylors/fees-and-scholarships.html','Partial',1),(45,28,'Jeffrey Cheah Foundation Scholarship — Sunway','Prestigious scholarship by the Jeffrey Cheah Foundation, one of Malaysia largest private foundations. Awards full scholarships to exceptionally deserving students at Sunway University, with strong focus on leadership and giving back.',90000.00,'MYR','ASEAN nationals, financial need + exceptional merit, minimum 8As SPM or equivalent, applying for Sunway University undergraduate, strong community service record.','2027-10-31','https://www.jeffreycheahfoundation.org/scholarships','Full',1),(46,23,'Malaysia-Japan International Institute of Technology (MJIIT) Scholarship','Special scholarship for the Malaysia-Japan collaboration programme at UTM. Students follow a Japanese-style engineering curriculum and may study in Japan for one semester. Covers full tuition and travel.',20000.00,'MYR','International students applying to MJIIT programmes at UTM, strong mathematics and science background, IELTS 5.5+ or JLPT N4+ preferred.','2027-07-31','https://www.utm.my/scholarship','Full',1),(47,29,'APU Women in Technology Scholarship','Dedicated scholarship encouraging women to pursue technology education at APU. Provides 50% tuition waiver for female students in computing, cybersecurity, and data science programmes.',25000.00,'MYR','Female students, international, applying for APU computing or technology programmes, minimum CGPA equivalent 3.0.','2026-11-05','https://www.apu.edu.my/scholarship','Partial',1),(48,22,'Yayasan Khazanah Global Scholarship — UPM','Offered by Khazanah Nasional, Malaysia sovereign wealth fund, for postgraduate study at top Malaysian universities including UPM. Full scholarship with return airfare and monthly allowance.',65000.00,'MYR','International students, Master or PhD applicants, CGPA 3.7+ equivalent, leadership potential, applying to UPM priority research areas.','2027-06-30','https://yayasankhazanah.com.my/scholarships/','Full',1);
