DROP TABLE IF EXISTS `universities`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `universities` (
  `university_id` int NOT NULL AUTO_INCREMENT,
  `country_id` int NOT NULL,
  `name` varchar(150) NOT NULL,
  `city` varchar(100) DEFAULT NULL,
  `website_url` varchar(255) DEFAULT NULL,
  `image_url` varchar(500) DEFAULT NULL,
  `description` text,
  `established_year` year DEFAULT NULL,
  `university_type` enum('Public','Private') DEFAULT 'Private',
  `world_ranking` int DEFAULT NULL,
  `national_ranking` int DEFAULT NULL,
  `acceptance_rate` decimal(5,2) DEFAULT NULL,
  `total_students` int DEFAULT NULL,
  `international_pct` decimal(5,2) DEFAULT NULL,
  `student_faculty_ratio` varchar(20) DEFAULT NULL,
  `campus_size` varchar(50) DEFAULT NULL,
  `research_output` enum('Very High','High','Medium','Low') DEFAULT NULL,
  `accreditations` varchar(500) DEFAULT NULL,
  `notable_programs` varchar(500) DEFAULT NULL,
  `facilities` varchar(500) DEFAULT NULL,
  `is_active` tinyint(1) DEFAULT '1',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`university_id`),
  KEY `idx_university_country` (`country_id`),
  KEY `idx_uni_country_active` (`country_id`,`is_active`),
