INSERT INTO `universities` VALUES (1,1,'Bangkok University','Bangkok','https://www.bu.ac.th','assets/images/bangkok.jpg','A leading private university in Bangkok offering programs in business, communication, engineering, and the arts. Popular with international students for its English-taught programs and vibrant city campus.',1962,'Private',601,3,35.00,18000,18.00,'15:1','100 acres','High','AACSB, ABET, MUA Thailand','Business Administration, Communication Arts, Engineering','Library, Sports Complex, Innovation Hub, Student Dormitory, Cafeteria',1,'2026-07-25 05:29:38','2026-08-22 05:55:40'),(2,1,'Chulalongkorn University','Bangkok','https://www.chula.ac.th','assets/images/chulalongkorn.png','Thailand\'s oldest and most prestigious university, consistently ranked among Asia\'s top 100. Renowned for medicine, engineering, business, and law with a strong international research community.',1917,'Public',201,1,25.00,37000,12.00,'12:1','270 acres','Very High','AACSB, ABET, EQUIS, MUA Thailand','Medicine, Engineering, Law, Architecture','Hospital, Research Centers, Olympic Pool, Library, 4 Dormitories',1,'2026-07-25 05:29:38','2026-08-22 05:55:40'),(3,1,'Mahidol University','Nakhon Pathom','https://www.mahidol.ac.th','assets/images/mahidol.jpeg','A leading research university in Southeast Asia, internationally recognized for health sciences, medicine, and public health. Over 40% of its programs are offered in English.',1943,'Public',251,2,30.00,29000,22.00,'10:1','175 acres','Very High','WFME, AACSB, MUA Thailand','Public Health, Medicine, Pharmacy, Dentistry','Hospital, Research Institute, Sports Center, International Dormitory',1,'2026-07-25 05:29:38','2026-08-22 05:55:40'),(4,1,'Thammasat University','Bangkok','https://www.tu.ac.th','assets/images/thammasat.jpg','One of Thailand\'s most respected universities, known for law, political science, economics, and social sciences. Thammasat\'s international programs attract students from across the region.',1934,'Public',601,4,28.00,32000,10.00,'14:1','120 acres','High','TBA, AACSB, EQUIS','Law, Economics, Political Science, Social Work','Democracy Monument Museum, Sports Complex, Library, Cafeteria',1,'2026-07-25 05:29:38','2026-08-22 05:55:40'),(5,1,'Chiang Mai University','Chiang Mai','https://www.cmu.ac.th','assets/images/chiangmai.jpg','The premier university in Northern Thailand offering outstanding programs in agriculture, humanities, sciences, and business in the culturally rich city of Chiang Mai.',1964,'Public',521,5,40.00,25000,8.00,'16:1','710 acres','High','AACSB, MUA Thailand','Agriculture, Tourism, Arts, Sciences','Museum, Botanical Garden, Sports Complex, Library, Dormitory',1,'2026-07-25 05:29:38','2026-08-22 05:55:40'),(6,1,'King Mongkut\'s University of Technology Thonburi','Bangkok','https://www.kmutt.ac.th','assets/images/king.webp','A top-tier science and technology university known for its strong industry partnerships and globally recognized engineering and technology programs.',1960,'Public',351,6,32.00,22000,15.00,'13:1','90 acres','Very High','ABET, IChemE, MUA Thailand','Engineering, Computer Science, Energy Technology','Innovation Factory, Maker Space, Robotics Lab, Green Campus',1,'2026-07-25 05:29:38','2026-08-22 05:55:40'),(7,1,'Kasetsart University','Bangkok','https://www.ku.ac.th','assets/images/kasetsart.webp','Thailand\'s leading university for agriculture and environmental sciences, also offering excellent programs in engineering, business, and economics.',1943,'Public',801,7,45.00,30000,5.00,'17:1','600 acres','Medium','AACSB, MUA Thailand','Agriculture, Veterinary Science, Economics, Fisheries','Agricultural Research Station, Botanical Garden, Library',1,'2026-07-25 05:29:38','2026-08-22 05:55:40'),(8,1,'Assumption University (ABAC)','Bangkok','https://www.au.edu','assets/images/assumption.webp','A private Catholic university with a highly international atmosphere. Offers English-taught programs in business, engineering, IT, and arts with students from over 80 countries.',1969,'Private',NULL,NULL,55.00,22000,20.00,'18:1','30 acres','Medium','AACSB, ONESQA Thailand','Business, Communication Arts, IT, Architecture','ABAC Cafeteria, Sports Complex, Chapel, Library, International Dorm',1,'2026-07-25 05:29:38','2026-08-22 05:55:40'),(9,1,'Asian Institute of Technology','Pathum Thani','https://www.ait.ac.th','assets/images/ait.jpg','An international postgraduate institution specializing in technology and management. Students from over 40 countries come here for master\'s and doctoral programs in English.',1959,'Private',NULL,NULL,40.00,2500,85.00,'8:1','80 acres','High','ABET, IChemE, AACSB','ICT, Environmental Engineering, Business Management, Energy','Research Centers, Language Center, Sports, International Dormitory',1,'2026-07-25 05:29:38','2026-08-22 05:55:40'),(10,1,'Rangsit University','Pathum Thani','https://www.rsu.ac.th','assets/images/rsu.jpg','A modern private university north of Bangkok known for pharmacy, aviation, creative arts, and international business programs in a vibrant and supportive campus environment.',1985,'Private',NULL,NULL,60.00,25000,12.00,'19:1','50 acres','Medium','ONESQA Thailand, Aviation Authority','Pharmacy, Aviation, Communication Arts, Architecture','Pharmacy Lab, Flight Simulator, Creative Arts Studio, Library',1,'2026-07-25 05:29:38','2026-08-22 05:55:40'),(11,2,'National University of Singapore','Singapore','https://www.nus.edu.sg','assets/images/Nus.jpg','Ranked Asia\'s best university and among the world\'s top 10, NUS offers comprehensive undergraduate and postgraduate programs across all disciplines with world-class research facilities.',1905,'Public',8,1,18.00,40000,35.00,'9:1','150 acres','Very High','AACSB, EQUIS, ABET, ACICS','Computing, Law, Medicine, Engineering, Business','University Cultural Centre, Museum, Utown, Research Labs, Swimming Complex',1,'2026-07-25 05:29:38','2026-08-22 05:55:40'),(12,2,'Nanyang Technological University','Singapore','https://www.ntu.edu.sg','assets/images/nanyang.webp','A global research university renowned for engineering, business, and science. NTU is consistently ranked among the world\'s top 20 universities and produces highly sought-after graduates.',1991,'Public',15,2,19.00,33000,32.00,'10:1','200 acres','Very High','AACSB, EQUIS, ABET','Engineering, Business, Science, Art Design and Media','The Hive, Research Centres, Sports Hall, Art Gallery, Dormitories',1,'2026-07-25 05:29:38','2026-08-29 16:18:40'),(13,2,'Singapore Management University','Singapore','https://www.smu.edu.sg','assets/images/smu.jpeg','Singapore\'s premier business and law university in the city centre. SMU\'s interactive, seminar-style teaching and strong industry connections prepare graduates for global leadership careers.',2000,'Public',511,3,20.00,10000,28.00,'7:1','15 acres','High','AACSB, EQUIS, AMBA, Singapore Bar','Business, Law, Accountancy, Information Systems, Social Sciences','City Campus, Lee Kong Chian School, Gym, Library, Seminar Rooms',1,'2026-07-25 05:29:38','2026-08-29 16:26:19'),(14,2,'Singapore University of Technology and Design','Singapore','https://www.sutd.edu.sg','assets/images/sutd1.webp','A unique design-centric university established in collaboration with MIT and Zhejiang University. SUTD combines technology, design, and humanities to produce innovative problem-solvers.',2009,'Public',NULL,4,22.00,2000,40.00,'6:1','12 acres','High','ABET, MIT Affiliation','Engineering Systems, Architecture, Computer Science, ISTD','Design Lab, Fab Lab, Library, Cohort Housing, Sports Facilities',1,'2026-07-25 05:29:38','2026-08-29 16:40:59'),(15,2,'Singapore University of Social Sciences','Singapore','https://www.suss.edu.sg','assets/images/suss.jpeg','Focuses on applied social sciences, law, and business with flexible learning pathways. SUSS serves full-time students and working professionals across Singapore.',2000,'Public',NULL,5,50.00,13000,15.00,'12:1','10 acres','Medium','SBF, MOE Singapore','Social Work, Psychology, Law, Logistics, Gerontology','City Campus, Digital Learning Hub, Library, Counselling Centre',1,'2026-07-25 05:29:38','2026-08-29 16:52:32'),(16,2,'James Cook University Singapore','Singapore','https://www.jcu.edu.sg','assets/images/jc.jpeg','The Singapore campus of Australia\'s James Cook University. Students earn an Australian degree at a Singapore campus, specializing in psychology, business, IT, and environmental science.',2003,'Private',NULL,NULL,55.00,2000,60.00,'11:1','5 acres','Medium','TEQSA Australia, CPE Singapore','Business, Psychology, IT, Marine Science','Modern Campus, Library, Student Lounge, Computer Labs',1,'2026-07-25 05:29:38','2026-08-29 17:01:31'),(17,2,'Singapore Institute of Management (SIM)','Singapore','https://www.sim.edu.sg','assets/images/sim.jpeg','One of Singapore\'s largest private education institutions, offering degree programs in partnership with top UK and Australian universities. Known for flexible study options.',1964,'Private',NULL,NULL,60.00,16000,30.00,'15:1','5 acres','Low','CPE Singapore, University of Stirling, RMIT','Business, Computing, Mass Communication, Psychology','City Campus, Library, Student Services Hub, Career Centre',1,'2026-07-25 05:29:38','2026-08-29 17:03:51'),(18,2,'PSB Academy','Singapore','https://www.psbacademy.edu.sg','assets/images/psb.jpg','A leading private education provider in Singapore offering degrees affiliated with UK universities. Popular programs include business, engineering, IT, and design.',1964,'Private',NULL,NULL,65.00,5000,45.00,'16:1','3 acres','Low','CPE Singapore, Glasgow Caledonian University','Business, Engineering, IT, Design','City Campus, Computer Labs, Library, Student Lounge',1,'2026-07-25 05:29:38','2026-08-29 17:09:08'),(19,2,'Kaplan Singapore','Singapore','https://www.kaplan.com.sg','assets/images/kaplan.jpeg','Provides accessible higher education through partnerships with UK and Australian universities. Popular for business, finance, hospitality, and accounting programs at affordable fees.',2004,'Private',NULL,NULL,70.00,8000,40.00,'18:1','2 acres','Low','CPE Singapore, University of Essex, University of Portsmouth','Finance, Hospitality, Accounting, Business','City Campus, Study Rooms, Computer Labs, Career Centre',1,'2026-07-25 05:29:38','2026-08-29 17:18:23'),(20,2,'MDIS (Management Development Institute of Singapore)','Singapore','https://www.mdis.edu.sg','assets/images/mdis.jpeg','One of Singapore\'s oldest private education institutions offering diploma and degree programs in partnership with UK universities, with a strong focus on business and engineering.',1956,'Private',NULL,NULL,68.00,4000,35.00,'17:1','4 acres','Low','CPE Singapore, University of Manchester, Coventry University','Business, Engineering, Fashion, Mass Communication','Campus Hub, Library, Computer Labs, Student Association Room',1,'2026-07-25 05:29:38','2026-08-29 17:19:42'),(21,3,'University of Malaya','Kuala Lumpur','https://www.um.edu.my','assets/images/um.jpeg','Malaysia\'s oldest and highest-ranked university. UM offers world-class education in medicine, engineering, law, and social sciences, consistently featured in global university rankings.',1949,'Public',65,1,22.00,22000,25.00,'11:1','309 acres','Very High','AACSB, ABET, MQA Malaysia','Medicine, Law, Engineering, Computer Science, Economics','University Hospital, Research Towers, Sports Complex, Lake Garden',1,'2026-07-25 05:29:38','2026-08-29 17:31:04'),(22,3,'Universiti Putra Malaysia','Serdang','https://www.upm.edu.my','assets/images/upm.webp','A comprehensive research university renowned for agriculture, engineering, medicine, and environmental sciences. UPM is a popular choice for international students seeking quality at affordable fees.',1931,'Public',201,2,30.00,27000,18.00,'13:1','1200 acres','Very High','AACSB, ABET, MQA Malaysia','Agriculture, Veterinary Science, Engineering, Medicine','Teaching Hospital, Agricultural Research Station, Sports Arena',1,'2026-07-25 05:29:38','2026-09-05 16:31:00'),(23,3,'Universiti Teknologi Malaysia','Johor Bahru','https://www.utm.my','assets/images/utm.jpeg','Malaysia\'s premier technological university, recognized for engineering, computing, and built environment programs. Strategically located near Singapore, offering strong industry ties.',1904,'Public',251,3,28.00,25000,20.00,'12:1','1200 acres','Very High','ABET, IChemE, MQA Malaysia','Civil Engineering, Computing, Architecture, Chemical Engineering','Maker Space, Engineering Labs, Sports Complex, Mosque',1,'2026-07-25 05:29:38','2026-09-05 16:36:48'),(24,3,'Universiti Kebangsaan Malaysia','Bangi','https://www.ukm.my','assets/images/ukm.jpg','A major research university with strong faculties in medicine, science, and engineering. UKM offers a welcoming environment for international students with competitive scholarship programs.',1970,'Public',301,4,32.00,26000,15.00,'13:1','1096 acres','Very High','AACSB, MQA Malaysia, JPA Malaysia','Medicine, Biotechnology, Engineering, Malay Studies','Hospital, Research Centres, Sports Complex, Cultural Centre',1,'2026-07-25 05:29:38','2026-09-05 16:40:25'),(25,3,'Universiti Sains Malaysia','George Town','https://www.usm.my','assets/images/usm1.webp','Malaysia\'s first research university located in the UNESCO heritage city of Penang. USM is renowned for science, health sciences, engineering, and humanities.',1969,'Public',228,5,30.00,27000,16.00,'12:1','780 acres','Very High','MQA Malaysia, AACSB, ABET','Pharmacy, Computer Science, Chemical Engineering, Medicine','Hospital, Engineering Campus, Arts Campus, Sports Complex',1,'2026-07-25 05:29:38','2026-09-05 17:02:02'),(26,3,'Taylor\'s University','Subang Jaya','https://www.taylors.edu.my','assets/images/taylor.webp','Malaysia\'s top-ranked private university known for hospitality and culinary arts, business, law, and architecture. Offers a vibrant, safe, and truly international campus experience.',1969,'Private',NULL,1,50.00,12000,30.00,'14:1','25 acres','Medium','MQA Malaysia, AACSB, ACCA, CPA Australia','Hospitality, Culinary Arts, Law, Business, Architecture','Teaching Kitchen, Law Moot Court, Sports Centre, Student Village',1,'2026-07-25 05:29:38','2026-09-05 17:06:21'),(27,3,'Monash University Malaysia','Subang Jaya','https://www.monash.edu.my','assets/images/mum.jpg','The Malaysian campus of Australia\'s top-ranked Monash University. Students receive the same globally recognized degree as the Australian campus at significantly lower tuition fees.',1998,'Private',57,2,35.00,9000,40.00,'10:1','25 acres','Very High','AACSB, EQUIS, ABET, MQA Malaysia','Engineering, Business, Law, Pharmacy, IT','Research Labs, Sports Hall, Library, Student Centre, Cafeteria',1,'2026-07-25 05:29:38','2026-09-05 17:24:46'),(28,3,'Sunway University','Subang Jaya','https://www.sunway.edu.my','assets/images/sun1.jpeg','A modern private university in the self-contained Sunway City township. Offers strong programs in business, computing, and sciences with an emphasis on student wellbeing and safety.',2011,'Private',NULL,3,55.00,8000,35.00,'15:1','20 acres','Medium','MQA Malaysia, ACCA, CFA Institute','Business, Actuarial Science, Computing, Psychology','Sunway Medical Centre, Sports Hall, Library, Student Residence',1,'2026-07-25 05:29:38','2026-09-05 17:29:50'),(29,3,'Asia Pacific University (APU)','Kuala Lumpur','https://www.apu.edu.my','assets/images/apu.jpg','One of Malaysia\'s top private universities for technology and computing, with one of the most diverse international student communities in Malaysia. Known for employability outcomes.',1993,'Private',NULL,4,60.00,13000,50.00,'14:1','8 acres','Medium','MQA Malaysia, BCS, CompTIA, EC-Council','Software Engineering, Cybersecurity, AI, Data Science','Technology Park Campus, Innovation Centre, Library, Gym',1,'2026-07-25 05:29:38','2026-09-06 16:06:05'),(30,3,'HELP University','Kuala Lumpur','https://www.help.edu.my','assets/images/help1.jpg','A well-established private university in Kuala Lumpur offering affordable programs in economics, business, law, and psychology with UK university affiliations and strong career support.',1986,'Private',NULL,5,65.00,7000,20.00,'16:1','15 acres','Low','MQA Malaysia, BPS UK, APA','Economics, Psychology, Law, Business','Library, Computer Labs, Student Lounge, Counselling Centre',1,'2026-07-25 05:29:38','2026-09-05 17:35:22');
