DROP TABLE IF EXISTS `users`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `users` (
  `user_id` int NOT NULL AUTO_INCREMENT,
  `full_name` varchar(100) NOT NULL,
  `email` varchar(150) NOT NULL,
  `password_hash` varchar(255) NOT NULL,
  `home_country_id` int DEFAULT NULL,
  `preferred_currency_code` char(3) DEFAULT 'MMK',
  `role` enum('Student','Admin') DEFAULT 'Student',
  `is_verified` tinyint(1) DEFAULT '0',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`user_id`),
  UNIQUE KEY `email` (`email`),
  UNIQUE KEY `uq_users_email` (`email`),
  KEY `preferred_currency_code` (`preferred_currency_code`),
  KEY `idx_users_email` (`email`),
  KEY `fk_user_country` (`home_country_id`),
  CONSTRAINT `fk_user_country` FOREIGN KEY (`home_country_id`) REFERENCES `countries` (`country_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `users_ibfk_1` FOREIGN KEY (`home_country_id`) REFERENCES `countries` (`country_id`),
  CONSTRAINT `users_ibfk_2` FOREIGN KEY (`preferred_currency_code`) REFERENCES `currencies` (`currency_code`)
) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

